abstract class Person { abstract void displayInfo(); } class Student extends Person { void displayInfo() { System.out.println("Student Name: Rahul"); System.out.println("Course: B.Tech"); } } class Teacher extends Person { void displayInfo() { System.out.println("Teacher Name: Amit"); System.out.println("Subject: Java"); } } public class Main { public static void main(String[] args) { Person s = new Student(); Person t = new Teacher(); s.displayInfo(); t.displayInfo(); } }